<?php
declare(strict_types=1);
require __DIR__ . '/lib.php';
portal_start_session(); if(!portal_is_authenticated()){header('Location: /');exit;}
$path=__DIR__.'/storage/daily-log.json';$days=is_file($path)?json_decode((string)file_get_contents($path),true):[];if(!is_array($days))$days=[];
$kindCounts=[];$verticals=[];$totalMinutes=0;$totalReturn=0.0;
foreach($days as $day){foreach(($day['entries']??[]) as $e){$kind=$e['kind']??'other';$v=$e['vertical']??'Unclassified';$m=(int)($e['minutes']??0);$r=(float)($e['return']??0);$kindCounts[$kind]=($kindCounts[$kind]??0)+1;if(!isset($verticals[$v]))$verticals[$v]=['tasks'=>0,'minutes'=>0,'return'=>0.0];$verticals[$v]['tasks']++;$verticals[$v]['minutes']+=$m;$verticals[$v]['return']+=$r;$totalMinutes+=$m;$totalReturn+=$r;}}
arsort($kindCounts);uasort($verticals,fn($a,$b)=>$b['tasks']<=>$a['tasks']);
