ialchars($e['vertical']??'Unclassified')?></span></td><td><span class="pill"><?=htmlspecialchars($e['kind']??'—')?></span></td><td><?=htmlspecialchars($e['title']??'')?></td><td><?=htmlspecialchars($e['impact']??'—')?></td><td class="prio"><?=htmlspecialchars($e['priority']??'—')?></td><td class="next"><?=htmlspecialchars($e['next']??'—')?></td><td><?=isset($e['minutes'])&&$e['minutes']!==null?(int)$e['minutes'].'m':'—'?></td><td><?=isset($e['return'])&&$e['return']!==null?'$'.number_format((float)$e['return'],0):'—'?></td></tr><?php endforeach;?></tbody></table></div><?php if(!empty($day['tomorrow_target'])):?><div class="tomorrow"><strong>Tomorrow →</strong> <?=htmlspecialchars($day['tomorrow_target'])?></div><?php endif;?></section><?php endforeach;?><section class="analytics"><p class="kicker">Task mix</p><div class="chips"><?php foreach($kindCounts as $k=>$c):?><span><?=htmlspecialchars($k)?> · <strong><?=$c?></strong></span><?php endforeach;?></div><p class="muted">Once time and return are populated, this page can calculate return per hour and compare allocation by vertical over time.</p></section></div></body></html>